import{_ as o,o as t,c as n,a2 as r}from"./chunks/framework.CZo9GF0W.js";const g=JSON.parse('{"title":"05 — Security & Safety Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"05-SECURITY.md","filePath":"05-SECURITY.md","lastUpdated":1789060268000}'),a={name:"05-SECURITY.md"};function s(d,e,i,c,l,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="_05-—-security-safety-requirements" tabindex="-1">05 — Security &amp; Safety Requirements <a class="header-anchor" href="#_05-—-security-safety-requirements" aria-label="Permalink to &quot;05 — Security &amp; Safety Requirements&quot;">​</a></h1><p>These are hard requirements, not aspirations. Each maps to a test that lives with the code it guards - <code>packages/core/test/guards.test.ts</code> and <code>redact.test.ts</code>, <code>packages/extension/test/secrets.test.ts</code>, <code>packages/ssh/test/knownHosts.test.ts</code>, each driver&#39;s <code>tls.test.ts</code>, and <code>packages/driver-mongodb/test/security.test.ts</code>.</p><h2 id="s1-secrets" tabindex="-1">S1. Secrets <a class="header-anchor" href="#s1-secrets" aria-label="Permalink to &quot;S1. Secrets&quot;">​</a></h2><ul><li><strong>S1.1</strong> Credentials are stored <em>only</em> via <code>vscode.SecretStorage</code> (OS keychain). Writing a credential to <code>settings.json</code>, any workspace file, <code>globalState</code>, or a log is a release blocker.</li><li><strong>S1.2</strong> <code>.vscode/pitta.connections.json</code> is validated against a JSON Schema that <strong>rejects a literal string</strong> in any password/passphrase field. Offending files are refused with a clear error, not silently accepted.</li><li><strong>S1.3</strong> Webviews never receive credentials. The connection form posts a draft with a <code>SecretRef</code> placeholder; resolution and testing happen in the extension host.</li><li><strong>S1.4</strong> <code>ResolvedProfile</code> is never <code>JSON.stringify</code>-ed into logs, telemetry, or error reports. Logger has a redaction pass keyed on known secret field names <em>and</em> on the resolved values themselves.</li><li><strong>S1.5</strong> Export/share of a profile strips all secrets and emits <code>{ kind: &#39;prompt&#39; }</code> refs.</li></ul><h2 id="s2-transport" tabindex="-1">S2. Transport <a class="header-anchor" href="#s2-transport" aria-label="Permalink to &quot;S2. Transport&quot;">​</a></h2><ul><li><strong>S2.1</strong> For any non-loopback host the connection form defaults to <code>sslmode=verify-full</code> and warns visibly if the user downgrades.</li><li><strong>S2.2</strong> <code>rejectUnauthorized: false</code> requires an explicit per-connection acknowledgement, and the connection is badged &quot;insecure TLS&quot; in the tree.</li><li><strong>S2.3</strong> SSH host keys are verified against <code>~/.ssh/known_hosts</code>; an unknown key prompts with the fingerprint. Never auto-accept.</li></ul><h2 id="s3-injection-surface" tabindex="-1">S3. Injection surface <a class="header-anchor" href="#s3-injection-surface" aria-label="Permalink to &quot;S3. Injection surface&quot;">​</a></h2><ul><li><strong>S3.1</strong> Every value the user types into a grid filter, cell editor, or parameter prompt goes out as a <strong>bind parameter</strong>. String interpolation of user values into SQL is banned; enforced by an eslint rule against template literals in <code>buildSelect</code>/<code>buildDml</code> paths.</li><li><strong>S3.2</strong> Identifiers (table/column names from the catalog) are the only interpolated fragments, and only through <code>quoteIdent()</code>, which escapes embedded quotes.</li><li><strong>S3.3 [MM]</strong> The rule is engine-independent, and stronger on the engines that do not use text at all: MongoDB filters and updates are built as BSON values from typed input, and Redis commands are argv arrays. There is no formatting step for user input to escape from, and the eslint rule extends to <code>buildSelect</code>/<code>buildEdits</code> in every driver.</li><li><strong>S3.4 [MM]</strong> MongoDB query text is parsed to an AST and converted to BSON. It is never executed as JavaScript — no <code>eval</code>, no <code>vm</code>, no <code>new Function</code> — so a snippet pasted from a ticket cannot reach the extension host, the file system, or the user&#39;s other credentials (ADR-042). Server-side JavaScript (<code>$where</code>, <code>$function</code>, <code>$accumulator</code>, <code>mapReduce</code>) is refused unless explicitly enabled and is always classified as an admin operation.</li></ul><h2 id="s4-destructive-operation-guards" tabindex="-1">S4. Destructive-operation guards <a class="header-anchor" href="#s4-destructive-operation-guards" aria-label="Permalink to &quot;S4. Destructive-operation guards&quot;">​</a></h2><ul><li><strong>S4.1</strong> <code>DROP</code>, <code>TRUNCATE</code>, <code>ALTER … DROP</code>, and <code>DELETE</code>/<code>UPDATE</code> without a <code>WHERE</code> clause are classified as destructive by the statement analyzer (real parse, not regex).</li><li><strong>S4.2</strong> On a <code>prod</code>-tagged connection, destructive statements need a typed confirmation (type the connection name). On dev, a single confirm, configurable to off.</li><li><strong>S4.3</strong> <code>pitta.query.blockUnqualifiedDml</code> (default true) refuses unqualified <code>UPDATE</code>/<code>DELETE</code> outright on any connection.</li><li><strong>S4.4</strong> <code>readOnly</code> profiles enforce read-only <strong>both</strong> server-side (<code>SET SESSION CHARACTERISTICS AS TRANSACTION READ ONLY</code>) and client-side.</li><li><strong>S4.5</strong> Row edits verify affected-row counts and roll back on mismatch (see 04 §6).</li><li><strong>S4.6 [MM]</strong> Classification is the driver&#39;s, from the engine&#39;s own metadata where it publishes any — Redis <code>COMMAND INFO</code> flags, MongoDB&#39;s operation verb plus an empty-filter test — combined with the shared heuristic by ADR-027&#39;s rule: destructive if either says so, and neither can downgrade the other.</li><li><strong>S4.7 [MM]</strong> An <strong>unclassifiable</strong> command on a <code>prod</code>-tagged connection is treated as destructive and needs the typed confirmation. Unknown fails closed where there is no trustworthy heuristic to fall back to (ADR-040).</li><li><strong>S4.8 [MM]</strong> <code>deleteMany({})</code> / <code>updateMany({})</code> are the analogue of DML with no <code>WHERE</code> and are covered by <code>pitta.query.blockUnqualifiedDml</code>. An aggregation containing <code>$out</code> or <code>$merge</code> is classified as a write by walking the pipeline, not by trusting the method name.</li><li><strong>S4.9 [MM]</strong> Redis: <code>KEYS</code> and <code>MONITOR</code> are refused rather than confirmed (O(N) server block; server-wide command stream). <code>FLUSHALL</code>, <code>FLUSHDB</code>, <code>SWAPDB</code>, <code>CONFIG SET</code>, <code>SHUTDOWN</code>, <code>MIGRATE</code>, <code>REPLICAOF</code>, <code>CLUSTER RESET</code>, <code>ACL SETUSER</code> and <code>EVAL</code> require the typed confirmation on prod.</li><li><strong>S4.10 [MM]</strong> Where an engine has no server-side read-only session, <code>readOnly</code> is enforced client-side by refusing anything classified <code>write</code> or <code>admin</code>, the badge reads &quot;client-side only&quot;, and the connection form recommends a read-only database user or ACL. A guarantee the server is not making is never presented as one.</li><li><strong>S4.11 [MM]</strong> Where a batch cannot be applied atomically, the apply dialog says so and the result reports which edits were applied. A rollback promise is never carried across from an engine that has one to an engine that does not (ADR-041).</li></ul><h2 id="s5-webview-hardening" tabindex="-1">S5. Webview hardening <a class="header-anchor" href="#s5-webview-hardening" aria-label="Permalink to &quot;S5. Webview hardening&quot;">​</a></h2><ul><li><strong>S5.1</strong> Strict CSP, nonce&#39;d scripts, <code>localResourceRoots</code> limited to the extension&#39;s <code>media/</code> dir. No remote script/style/font/image loads.</li><li><strong>S5.2</strong> All <code>postMessage</code> payloads validated with <code>zod</code> on receipt in both directions. Unknown message → dropped + logged.</li><li><strong>S5.3</strong> Cell values are rendered as <strong>text nodes</strong>. No <code>innerHTML</code>, no <code>dangerouslySetInnerHTML</code> anywhere — a row of data must never be able to execute. Markdown/HTML preview of a cell, if added, renders in a sandboxed sub-frame with its own CSP.</li></ul><h2 id="s6-third-party-code" tabindex="-1">S6. Third-party code <a class="header-anchor" href="#s6-third-party-code" aria-label="Permalink to &quot;S6. Third-party code&quot;">​</a></h2><ul><li><strong>S6.1</strong> Dependency allowlist; every new runtime dep needs a note in <code>09-DECISIONS.md</code>.</li><li><strong>S6.2</strong> <code>pnpm audit</code> + Dependabot/Renovate gate CI. No <code>postinstall</code> scripts in runtime deps.</li><li><strong>S6.3</strong> Prefer pure-JS deps so the VSIX stays platform-neutral. Native modules would require per-platform VSIX builds — avoided (node-postgres is pure JS; <code>ssh2</code> crypto bindings are optional and fall back to JS).</li><li><strong>S6.4 [MM]</strong> The same rule picks the non-relational clients: <code>mongodb</code> (with <code>bson</code>&#39;s JS path) and <code>ioredis</code>, with the optional native packages — <code>mongodb-client-encryption</code>, <code>kerberos</code>, <code>@mongodb-js/zstd</code>, <code>snappy</code> — excluded from the bundle and the features needing them not claimed (ADR-046).</li></ul><h2 id="s7-privacy" tabindex="-1">S7. Privacy <a class="header-anchor" href="#s7-privacy" aria-label="Permalink to &quot;S7. Privacy&quot;">​</a></h2><ul><li><strong>S7.1</strong> Telemetry off by default, opt-in, respects <code>telemetry.telemetryLevel</code>. Documented event list in the README.</li><li><strong>S7.2</strong> No SQL text, no schema names, no hostnames, no row data ever leaves the machine. Telemetry, if enabled, carries only counters and error <em>classes</em>.</li><li><strong>S7.3</strong> Query history is local-only; <code>prod</code> excluded by default.</li><li><strong>S7.4 [MM]</strong> Sampling is reading. The MongoDB schema inference and the Redis key sample read real user data to build the tree and the completion index; both stay in the extension host, both obey the metadata cache&#39;s TTL and the same on-disk rules as any other cached metadata, and neither is ever included in telemetry.</li></ul>',16)])])}const p=o(a,[["render",s]]);export{g as __pageData,p as default};
